from PIL import Image
import numpy as np

# Load the image
img = Image.open('/home/ctfplayer/ctf_files/short-circuit.jpg')
img_array = np.array(img)

# Convert to binary (1 for dark pixel, 0 for light pixel)
# Assuming the circuit traces are dark on a light background
threshold = 128
binary = (img_array < threshold).astype(int)

# Convert binary rows to ASCII
results = []
for i, row in enumerate(binary):
    # Convert row to a binary string
    bin_str = ''.join(str(x) for x in row[:112])  # Consider only first 112 bits (mentioned in clue)

    # If the row has significant dark pixels (> 20)
    if sum(row) > 20:
        # Try to decode the binary in 8-bit chunks
        try:
            ascii_str = ""
            for j in range(0, len(bin_str), 8):
                if j+8 <= len(bin_str):
                    byte = bin_str[j:j+8]
                    ascii_str += chr(int(byte, 2))

            # Check if it contains "flag" or has reasonable ASCII content
            if any(x in ascii_str.lower() for x in ['flag', '{', '}']) or ascii_str.isprintable():
                results.append(f"Row {i}: {ascii_str}")
        except:
            pass

# Print results
if results:
    print(f"Found {len(results)} potential flag rows")
    for r in results[:50]:  # Show first 50 results
        print(r)
else:
    print("No potential flag rows found")

# Now try with 7-bit ASCII
results = []
for i, row in enumerate(binary):
    # Try to interpret first 112 bits directly as flag characters
    if sum(row) > 20:
        try:
            ascii_str = ""
            for j in range(0, min(112, len(row)), 7):
                if j+7 <= len(row):
                    byte = ''.join(str(x) for x in row[j:j+7])
                    if int(byte, 2) < 128:  # Valid ASCII
                        ascii_str += chr(int(byte, 2))

            if len(ascii_str) > 5 and ascii_str.isprintable() and not ascii_str.isspace():
                results.append(f"Row {i} (7-bit): {ascii_str}")
        except:
            pass

# Print 7-bit results
if results:
    print(f"\nFound {len(results)} potential 7-bit flag rows")
    for r in results[:50]:
        print(r)
else:
    print("\nNo potential 7-bit flag rows found")

# Try to find the flag looking at positions where the challenge mentions 112 things
if binary.shape[1] >= 112:
    print("\nChecking bits at position 112 in each row:")
    flag_bits = []
    for i, row in enumerate(binary):
        if len(row) > 112:
            flag_bits.append(row[111])  # Zero-indexed, so position 112 is index 111

    # Try to convert every 8 bits to a character
    flag_str = ""
    for i in range(0, len(flag_bits), 8):
        if i+8 <= len(flag_bits):
            byte = ''.join(str(x) for x in flag_bits[i:i+8])
            flag_str += chr(int(byte, 2))

    print(f"Potential flag from position 112 bits: {flag_str}")

# Count the number of thin traces (rows with exactly 112 "1" bits)
thin_rows = [i for i, row in enumerate(binary) if sum(row) == 112]
print(f"\nFound {len(thin_rows)} rows with exactly 112 dark pixels")
if thin_rows:
    for idx in thin_rows[:10]:  # Show first 10
        print(f"Row {idx}")
